package dev.smpcristalix.pvpcombat.service;
import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import dev.smpcristalix.pvpcombat.data.PlayerProfile;import org.bukkit.entity.Player;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
/** Снимает ровно одну доступную ступень и соблюдает cooldown штрафа смерти. */
public final class DeathPenaltyService{private final StatsService stats;private PvPCombatSettings settings;public DeathPenaltyService(StatsService s,PvPCombatSettings c){stats=s;settings=c;}public void reload(PvPCombatSettings s){settings=s;}public String apply(Player player){PlayerProfile p=stats.profile(player.getUniqueId());long now=System.currentTimeMillis(),cd=settings.statLossCooldownMinutes()*60000L;if(now-p.lastStatLossAt()<cd)return null;List<Candidate> c=new ArrayList<>();if(p.abilityLevel()>0)c.add(new Candidate("Умения",settings.deathWeight("ability"),()->p.abilityLevel(p.abilityLevel()-1)));if(p.damageLevel()>0)c.add(new Candidate("Урон",settings.deathWeight("damage"),()->p.damageLevel(p.damageLevel()-1)));if(p.healthStep()>stats.minHealthStep())c.add(new Candidate("Здоровье",settings.deathWeight("health"),()->p.healthStep(p.healthStep()-1)));if(p.speedLevel()>0)c.add(new Candidate("Скорость",settings.deathWeight("speed"),()->p.speedLevel(p.speedLevel()-1)));if(p.satietyLevel()>0)c.add(new Candidate("Сытость",settings.deathWeight("satiety"),()->p.satietyLevel(p.satietyLevel()-1)));int total=c.stream().mapToInt(Candidate::weight).sum();if(total<=0)return null;int r=ThreadLocalRandom.current().nextInt(total);for(Candidate x:c){r-=x.weight();if(r<0){x.action().run();p.lastStatLossAt(now);stats.apply(player);return x.name();}}return null;}private record Candidate(String name,int weight,Runnable action){}}
